  (* [comment removed for export] *)
  Definition wv_loop_stmt (n : nat) : Prop :=
    forall (s : bool) R M (model : Model) q c b1 l1 b2 l2 bs1 bs2,
      (length (bs1 ++ bs2) <= n)%nat ->
      m_vm_lazy model = lazy -> MInv A model -> m_halted model = None ->
      fd_lookup (m_fds model) (Z_to_bv 64 fd) = Some (FdChannel (Z_to_bv 64 fd)) ->
      m_channel_reader model = true ->
      wv_regs s R q c (l1 + l2) ->
      wv_iov (mrestrict H M) q c b1 l1 b2 l2 bs1 bs2 ->
      l1 + l2 <= 2 ^ 30 ->
      rdn ASEGS (mrestrict H M) (Z_to_bv 64 (f + 120)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 fd)) ->
      wv_done R M model ->
      srealizes ASEGS scfg (mkCfg (mkst R (wv_pc s) M rom) model) (t_emit (map (WriteEv (Z_to_bv 64 fd)) (bs1 ++ bs2)) K).

  Lemma wv_buf_len : forall MV b l bs, wv_buf MV b l bs -> length bs = Z.to_nat l.
  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "SD0!1,1|600;|30;!1+0!1,11!1+H2!2'^<,^=#4!2'_L#4#3|10;!2'_Y!1,76!1,7|50f;!1+^53!3+5+_=!2'`G!1'`H#2/lazy;,`D!2'^<,^=#6!2'_L#7#6!2'_L#8#7!2'^<,^=#7!2'_L#;#:!2'_L#<#;!2'^<?7!2'_L#@#?!2+9!3+5+D#?,^=!2+9!2'^<A/qlo;!2'^</qhi;#@!3+58!4'^6'^7#E!2'^80#D!1'^9#C!2,^:3#B$MV;R%~R!1+00!1+^52$b;R+D$l;R+D$bs;R3$H0;R!4'`F#4#3#2#1!5'_N4!2+^;!2'^<,^=#3!2+^;!2'^<57!2+^;!2+9!3+5+D#3,^=!2+9!2'^<5/qlo;!2'^</qhi;#4!2+^;!3+58!4'^6'^7#5!2'^80#4!1'^9#3!2,^:3#2%x;R+D%~R!2+^;!2'^<#5#1!2'^I#1!2'_L#5#49!3+5+^C!2'`S2#2!1'^9#3$~R4$~R!2+^;!2'^<,^=#4!2+^;!2'^<!2'_L#5#47!2+^;!2+9!3+5+D#4,^=!2+9!2'^<!2'_L#5#4/qlo;!2'^</qhi;#5!2+^;!3+58!4'^6'^7#6!2'^80#5!1'^9#4!2,^:3#3%x;R+D%~R!2+^;!2'^<#6#1!2'^I#1!2'_L#6#59!2$_H;R:$H0;R!2+^;:!2+^;!2'^<;7!2+^;!2+9!3+5+D#6,^=!2+9!2'^<;/qlo;!2'^</qhi;#7!2+^;!3+58!4'^6'^7#8!2'^80#7!1'^9#6!2,^:3#5%x;R+D%~R!2+^;!2'^<#8#1!2'^I#1<9!5'_N=!2+^;!2'^<<7!2+^;!2+9!3+5+D#7,^=!2+9!2'^<</qlo;!2'^</qhi;#8!2+^;!3+58!4'^6'^7#9!2'^80#8!1'^9#7!2,^:3#6%x;R+D%~R!2+^;!2'^<#9#1!2'^I#1!2'_L#9#89!3+5+^C!2'`S2#6!1'^9#7$~R=$~R!2+^;!2'^<!2'_L#9#87!2+^;!2+9!3+5+D#8,^=!2+9!2'^<!2'_L#9#8/qlo;!2'^</qhi;#9!2+^;!3+58!4'^6'^7#:!2'^80#9!1'^9#8!2,^:3#7%x;R+D%~R!2+^;!2'^<#:#1!2'^I#1!2'_L#:#99!2$_H0;R!2'^<,^=#9$H0;R!2+^;!2'^<>7!2+^;!2+9!3+5+D#:,^=!2+9!2'^<>/qlo;!2'^</qhi;#;!2+^;!3+58!4'^6'^7#<!2'^80#;!1'^9#:!2,^:3#9%x;R+D%~R!2+^;!2'^<#<#1!2'^I#1?9!5'_N@!2+^;!2+9!3+5+D#;,^=!2+9!2'^<?/qlo;!2'^</qhi;#<!2+^;!3+58!4'^6'^7#=!2'^80#<!1'^9#;!2,^:3#:%x;R+D%~R!2+^;!2'^<#=#1!2'^I#1!2'_L#=#<9!3+5+^C!2'`S2#:!1'^9#;$~R@$~R!2+^;!2+9!3+5+D#<,^=!2+9!2'^<!2'_L#=#</qlo;!2'^</qhi;#=!2+^;!3+58!4'^6'^7#>!2'^80#=!1'^9#<!2,^:3#;%x;R+D%~R!2+^;!2'^<#>#1!2'^I#1!2'_L#>#=9!2$_H1;R!2'^<!2'_L#>#=7$H0;R!2+^;!2+9!3+5+D#>,^=!2+9!2'^<!2'_L#?#>/qlo;!2'^</qhi;#?!2+^;!3+58!4'^6'^7#@!2'^80#?!1'^9#>!2,^:3#=%x;R+D%~R!2+^;!2'^<#@#1!2'^I#1A9!5'_NB!2+^;!3+58!4'^6'^7#A!2'^80#@!1'^9#?!2,^:3#>%x;R+D%~R!2+^;!2'^<#A#1!2'^I#1!2'_L#A#@9!3+5+^C!2'`S2#>!1'^9#?$~RB$~R!2+^;!3+58!4'^6'^7#B!2'^80#A!1'^9#@!2,^:3#?%x;R+D%~R!2+^;!2'^<#B#1!2'^I#1!2'_L#B#A9!2$_H2;R!2+9!3+5+D#A,^=!2+9!2'^<!2'_L#B#A/qlo;!2'^</qhi;#B$H0;R!2+^;!3+58!4'^6'^7#D!2'^80#C!1'^9#B!2,^:3#A%x;R+D%~R!2+^;!2'^<#D#1!2'^I#1!2'_L#D#C9!5'_NC%x;R+D%~R!2+^;!2'^<#E#1!2'^I#1!2'_L#E#D9!3+5+^C!2'`S2#B!1'^9#C$~RC$~R%x;R+D%~R!2+^;!2'^<#F#1!2'^I#1!2'_L#F#E9!2$B5;R!3+58!4'^6'^7#G!2'^80#F!1'^9#E!2,^:3#D$_H3;R%x;R+D%~R!2+^;!2'^<#H#1!2'^I#1!2'_L#H#G9!6'`\'^7#I!1'^9#G!2'^80#H#F#2#2#1#1#2#1#1#2#1#1#2#1#1#2#1#1").
